    32	    if (!result.context || !parseWireCounter(result.context.clientEpoch) || !parseWireCounter(result.activationTokenFloor)) throw unavailable();
    33	    this.context = result.context; this.activationToken = result.activationTokenFloor; this.scopeId = result.activeScopeId; this.scopeGeneration = result.scopeGeneration; this.snapshotState = null;
