    35	  }
    36	  async activateScope(scopeId: string | null): Promise<ScopeActivation> {
    37	    if (!this.context || !this.activationToken) throw unavailable();
    38	    const token = incrementWireCounter(this.activationToken); if (!token) throw { ...unavailable(), code: "COUNTER_EXHAUSTED" as const };
    39	    const operation = ++this.operation; const context = this.context; this.activationToken = token; this.scopeId = scopeId; this.snapshotState = null;
    40	    try {
    41	      const result = await this.call<ScopeActivation>(NATIVE_SSH_FORWARD_COMMANDS.activateScope, { input: { context, activationToken: token, scopeId } });
    42	      if (operation !== this.operation || result.context.clientEpoch !== context.clientEpoch || result.activationToken !== token || result.scopeId !== scopeId) return result;
    43	      this.scopeGeneration = result.scopeGeneration; this.snapshotState = result.snapshot; return result;
    44	    } catch (error) { if (parseError(error).code === "ACTIVATION_SUPERSEDED") throw error; throw error; }
    45	  }
