    48	  updateProfile(profileId: string, expectedGeneration: WireCounter, profile: SshForwardProfile): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.updateProfile, { profileId, expectedGeneration, profile, expectedProfilesRevision: this.requireSnapshot().profilesRevision }); }
    49	  deleteProfile(profileId: string, expectedGeneration: WireCounter): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.deleteProfile, { profileId, expectedGeneration, expectedProfilesRevision: this.requireSnapshot().profilesRevision }); }
