    53	  listKeys(): Promise<KeyInventory> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.listKeys, {}); }
    54	  approveHost(profileId: string, expectedGeneration: WireCounter, challengeId: string, algorithm: string, fingerprint: string): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.approveHost, { profileId, expectedGeneration, challengeId, algorithm, fingerprint, expectedTrustRevision: this.requireSnapshot().trustRevision }); }
    55	  async purgeScope(scopeId: string, knownScopes: KnownScopesInput): Promise<{ scopeId: string; purged: boolean }> {
    56	    if (!this.context || !this.activationToken) throw unavailable();
    57	    return this.call(NATIVE_SSH_FORWARD_COMMANDS.purgeScope, { input: { context: this.context, activationToken: this.activationToken, scopeId, knownScopes } });
    58	  }
    59	  subscribe(listener: (event: SshForwardHostEvent) => void): () => void { this.listeners.add(listener); return () => this.listeners.delete(listener); }
    60	  dispose(): void { if (this.disposed) return; this.disposed = true; ++this.operation; this.unlisten?.(); this.unlisten = null; }
    61	  private async command<T>(command: string, extra: Record<string, unknown>): Promise<T> {
    62	    if (!this.context || !this.activationToken || !this.scopeId || !this.scopeGeneration) throw unavailable();
    63	    const result = await this.call<T>(command, { input: { context: this.context, activationToken: this.activationToken, scopeId: this.scopeId, scopeGeneration: this.scopeGeneration, ...extra } });
    64	    if (this.isSnapshot(result)) this.snapshotState = result; return result;
    65	  }
    66	  private requireSnapshot(): SshForwardSnapshot { if (!this.snapshotState) throw unavailable(); return this.snapshotState; }
    67	  private isSnapshot(value: unknown): value is SshForwardSnapshot { return Boolean(value && typeof value === "object" && "profilesRevision" in value); }
    68	  private async call<T>(command: string, input: Record<string, unknown>): Promise<T> { try { return await invoke<T>(command, input); } catch (error) { throw parseError(error); } }
    69	  private async installListener(): Promise<void> { if (this.listening) return this.listening; this.listening = listen<SshForwardEventHint>("ssh-forward:changed", (event) => this.handleHint(event.payload)).then((unlisten) => { if (this.disposed) unlisten(); else this.unlisten = unlisten; }); return this.listening; }
    70	  private handleHint(hint: SshForwardEventHint): void {
    71	    const context = this.context;
    72	    if (!context || hint.desktopInstanceId !== context.desktopInstanceId || hint.managerSessionId !== context.managerSessionId || hint.clientEpoch !== context.clientEpoch || hint.activationToken !== this.activationToken || hint.scopeId !== this.scopeId) return;
    73	    if (![hint.scopeGeneration, hint.profilesRevision, hint.trustRevision].every(parseWireCounter)) return;
    74	    for (const listener of this.listeners) listener({ type: "changed", hint });
    75	  }
    76	}
